{
    // Your code here
    vedioHandle.isPlay++;
    if (vedioHandle.isPlay == 1) lv_label_set_text(ui_ScrVedioShow_LabelPlay, LV_SYMBOL_PLAY);
    else if (vedioHandle.isPlay == 0) lv_label_set_text(ui_ScrVedioShow_LabelPlay, LV_SYMBOL_PAUSE);
}

