void scr_vedio_show_cont_main_eh(lv_event_t* e)
{
    isVerGesture = 0;
    lv_obj_add_flag(ui_ScrVedioShow_ContVolume, LV_OBJ_FLAG_HIDDEN);
}

void scr_vedio_show_cont_main_eh2(lv_event_t* e)
{
    //printf("pressing\n");
    if (isVerGesture == 0) return; /*没有触发手势事件*/

    lv_point_t point;
    lv_indev_get_vect(lv_indev_active(), &point); /*获取滑动的x,y向量值*/

    int8_t val = 0;
    //if (point.y >= -2 && point.y <= 2)return;  
    if (point.y == 0)return;


    /*修改音量值*/

    val = -(point.y / 2);
    int32_t curVal = lv_bar_get_value(ui_ScrVedioShow_BarVolume);
    int32_t maxVal = lv_bar_get_max_value(ui_ScrVedioShow_BarVolume);
    if (curVal + val > maxVal)
    {
        lv_bar_set_value(ui_ScrVedioShow_BarVolume, maxVal, LV_ANIM_OFF);
    }
    else if(curVal + val < 0)
    {
        lv_bar_set_value(ui_ScrVedioShow_BarVolume, 0, LV_ANIM_OFF);
    }
    else
    {
        _ui_bar_increment(ui_ScrVedioShow_BarVolume, val, LV_ANIM_OFF);
    }

    printf("vect_y=%d,curVal:%d\n",point.y, lv_bar_get_value(ui_ScrVedioShow_BarVolume));

    //scr_vedio_show_timer = lv_timer_create(scr_vedio_show_timer_cb, 500, NULL);

    //lv_indev_wait_release(lv_indev_active());   
}




